/**
 * The illustrated icons, and which icon names have one.
 *
 * A block says `icon: "gem"`, and that name used to pick a thin line glyph.
 * Every name below now has a drawing in public/icons of the same name, so the
 * block picks up the illustration without anything being re-typed in the
 * admin and without a single row changing in the database.
 *
 * The drawings are generated by scripts/make-illustrations.mjs — the whole set
 * comes out of one file so the circle, the shadow, the sparkles and the stroke
 * weight are identical in every one of them. The test in tests/unit keeps this
 * list and that folder honest about each other.
 *
 * Plain values and one pure function: no imports, so this is safe to use from
 * a server component, a client component or a test.
 */

export const ILLUSTRATED = [
  'art',
  'award',
  'bag',
  'chat',
  'check',
  'clock',
  'compass',
  'eye',
  'factory',
  'gem',
  'handshake',
  'heart',
  'lightbulb',
  'mail',
  'palette',
  'pencil',
  'phone',
  'pin',
  'reorder',
  'ruler',
  'rush',
  'shield',
  'shirt',
  'sparkle',
  'star',
  'tag',
  'target',
  'truck',
  'users',
] as const;

export type IllustratedName = (typeof ILLUSTRATED)[number];

const SET: ReadonlySet<string> = new Set(ILLUSTRATED);

/** The drawing for an icon name, or null when that name has none yet. */
export function illustrationFor(icon: string | null | undefined): string | null {
  const name = String(icon ?? '')
    .trim()
    .toLowerCase();
  return SET.has(name) ? `/icons/${name}.svg` : null;
}

/** True for a file the browser should be handed as it is, rather than resized. */
export function isVector(src: string | null | undefined): boolean {
  return /\.svg(\?|#|$)/i.test(String(src ?? ''));
}
